         public void SetApiVersionsFromProfile(AzureStackProfile profile)
         {
             var assembly = Assembly.GetExecutingAssembly();
             using (Stream stream = assembly.GetManifestResourceStream(profile.GetManifestName()))
             {
                 Dictionary<string, Dictionary<string, JsonElement>> allProfile;
                 using (var jsonDoc = JsonDocument.Parse(BinaryData.FromStream(stream).ToMemory()))
                 {
                     allProfile = new Dictionary<string, Dictionary<string, JsonElement>>();
                     foreach (var ns in jsonDoc.RootElement.EnumerateObject())
                     {
                         var inner = new Dictionary<string, JsonElement>();
                         foreach (var entry in ns.Value.EnumerateObject())
                         {
                             inner[entry.Name] = entry.Value.Clone();
                         }
                         allProfile[ns.Name] = inner;
                     }
                 }
                 var armProfile = allProfile["resource-manager"];
                 foreach (var keyValuePair in armProfile)
